def join_tuples(test_list):
    # Initialize an empty dictionary to store tuples with similar initial elements
    res = {}
    # Iterate through each tuple in the list
    for ele in test_list:
        # If the first element of the tuple is already a key in the dictionary, append the tuple to the list of values
        if ele[0] in res:
            res[ele[0]].append(ele)
        # Otherwise, create a new key-value pair in the dictionary with the first element as the key and the tuple as the value
        else:
            res[ele[0]] = [ele]
    # Convert the dictionary values to a list of tuples and return it
    return list(res.values())

# Test the function with the provided test case
assert join_tuples([(5, 6), (5, 7), (6, 8), (6, 10), (7, 13)]) == [(5, 6, 7), (6, 8, 10), (7, 13)]

def check_Consecutive(lst):
    # Check if the list is empty or has only one element
    if len(lst) <= 1:
        return True

    # Sort the list
    lst.sort()

    # Iterate through the sorted list and check for consecutive numbers
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1] + 1:
            return False

    return True

# Test the function with the provided test case
assert check_Consecutive([1, 2, 3, 4, 5]) == True

def is_Isomorphic(str1, str2):
    # Check if the lengths of the two strings are different
    if len(str1) != len(str2):
        return False

    # Create dictionaries to store the mapping of characters from str1 to str2 and vice versa
    map_str1_to_str2 = {}
    map_str2_to_str1 = {}

    # Iterate through the characters of both strings
    for char1, char2 in zip(str1, str2):
        # Check if the current character of str1 is already mapped to a different character in str2
        if char1 in map_str1_to_str2 and map_str1_to_str2[char1] != char2:
            return False
        # Check if the current character of str2 is already mapped to a different character in str1
        if char2 in map_str2_to_str1 and map_str2_to_str1[char2] != char1:
            return False
        # Update the mappings
        map_str1_to_str2[char1] = char2
        map_str2_to_str1[char2] = char1

    # If all characters are mapped correctly, the strings are isomorphic
    return True

# Test the function with the provided test case
assert is_Isomorphic("paper", "title") == True

def sort_on_occurence(test_list):
    # Create a dictionary to count occurrences of the first element of each tuple
    count_dict = {}
    for sub in test_list:
        if sub[0] in count_dict:
            count_dict[sub[0]] += 1
        else:
            count_dict[sub[0]] = 1

    # Sort the list based on the count of the first element in descending order
    res = sorted(test_list, key=lambda x: count_dict[x[0]], reverse=True)

    # Create a new list to store the result with the count appended
    res1 = []
    for sub in res:
        if sub[0] not in res1:
            res1.append(sub + (count_dict[sub[0]],))
        else:
            res1[-1] += (count_dict[sub[0]],)

    return res1

# Test the function with the provided test case
assert sort_on_occurence([(1, 'Jake'), (2, 'Bob'), (1, 'Cara')]) == [(1, 'Jake', 'Cara', 2), (2, 'Bob', 1)]

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    nested = True
            else:
                return False

    return nested and not stack

